<section class="page-head"><div><span class="eyebrow"><?=e(__('nav.food'))?></span><h1><?=e($restaurant['name'])?></h1><p><?=e($restaurant['description']?:$restaurant['business_name'])?></p></div></section><div class="card-grid"><?php foreach($menu as $m):?><article class="content-card"><div class="card-top"><span class="tag"><?=e($m['category_name'])?></span><strong><?=e(money($m['price']))?></strong></div><h3><?=e($m['name'])?></h3><p><?=e($m['description']?:'')?></p><form method="post" action="<?=e(url('/food/'.$restaurant['id'].'/order'))?>" class="form-stack"><?=csrf_field()?><input type="hidden" name="menu_item_id" value="<?=e($m['id'])?>"><input type="number" name="quantity" value="1" min="1" max="50"><input name="address" placeholder="<?=e(__('common.address'))?>" required><button class="btn primary" type="submit"><?=e(__('food.order'))?></button></form></article><?php endforeach;?></div>
